// Photographic artwork shares one perspective camera with ground, people and conductor topology.
export const hybridSources={hybridGround:'dark-earth-v63.png'};
export const hybridDefaults={hybridStreetEnabled:true,hybridTravel:5.55,hybridPan:2.6,hybridPanStart:23.2,hybridPanDuration:2.2,hybridFocal:820,hybridHorizonStart:220,hybridHorizonEnd:20,hybridCameraHeight:2.4,hybridActorDepth:7.2,hybridActorHeight:2.05,hybridActorX:0,hybridBackdropDepth:18,hybridForegroundDepth:8.5,hybridWireDarkness:'#777b72',hybridWireWidth:2.2,hybridWireSag:.28,hybridWireRelease:12.95,hybridWireFallTime:8.2,hybridWireAnchors:{left:[.19,.29],right:[.87,.25]},hybridSalvageAttach:true,hybridRuinAnchorU:.855,hybridRuinAnchorV:.25,hybridCableReach:10,hybridCableRise:1,hybridSalvageGroundLight:.7,hybridSalvageSkyLight:.82,hybridWalkTravel:1.35,hybridWalkCadence:1.1,hybridActorTrack:1,hybridActorEndX:800,hybridWireNearDepth:8.2};
const clamp=x=>Math.max(0,Math.min(1,x)),smooth=x=>{x=clamp(x);return x*x*(3-2*x)},lerp=(a,b,q)=>a+(b-a)*q;
export function hybridCamera(time,input={}){const f={...hybridDefaults,...input},q=smooth((time-13.3)/12.1),panProgress=Math.max(0,(time-f.hybridPanStart)/Math.max(.1,f.hybridPanDuration)),pan=panProgress<=1?panProgress*panProgress*(2-panProgress):panProgress;return {x:-f.hybridPan*pan,z:Math.max(0,Math.min(f.hybridTravel,f.hybridActorDepth-.8,f.hybridForegroundDepth-1,f.hybridBackdropDepth-1))*q,height:f.hybridCameraHeight,focal:f.hybridFocal,horizon:lerp(f.hybridHorizonStart,f.hybridHorizonEnd,q),q,pan};}
export function projectHybrid(point,camera){const d=point[2]-camera.z;if(d<.05)return null;return [480+(point[0]-camera.x)*camera.focal/d,camera.horizon+(camera.height-point[1])*camera.focal/d,d];}
export function imageAnchorWorld(u,v,depth,input={}){const f={...hybridDefaults,...input};return [(u*960-480)*depth/f.hybridFocal,f.hybridCameraHeight-(v*540-f.hybridHorizonStart)*depth/f.hybridFocal,depth];}
export function hybridStreetActor(time,input={}){const f={...hybridDefaults,...input},cam=hybridCamera(time,f),d=f.hybridActorDepth-cam.z,target=lerp(480,f.hybridActorEndX,smooth((time-f.hybridPanStart)/f.hybridPanDuration)),worldX=lerp(f.hybridActorX,cam.x+(target-480)*d/cam.focal+f.hybridActorX,f.hybridActorTrack),foot=projectHybrid([worldX,0,f.hybridActorDepth],cam),head=projectHybrid([worldX,f.hybridActorHeight,f.hybridActorDepth],cam);return {camera:cam,x:foot[0],feet:foot[1],height:foot[1]-head[1],head,worldX};}

let wallTexture;function wallMaterial(){if(wallTexture)return wallTexture;const cv=Object.assign(document.createElement('canvas'),{width:256,height:512}),c=cv.getContext('2d'),im=c.createImageData(256,512);for(let y=0;y<512;y++)for(let x=0;x<256;x++){const i=(y*256+x)*4,n=((Math.imul(x+17,15485863)^Math.imul(y+7,32452843))>>>0)%21-10,v=51+n;im.data[i]=v;im.data[i+1]=v+1;im.data[i+2]=v;im.data[i+3]=255;}c.putImageData(im,0,0);c.strokeStyle='#17191688';c.lineWidth=1;for(let k=0;k<7;k++){c.beginPath();c.moveTo(30+k*37,0);for(let y=0;y<=512;y+=32)c.lineTo(30+k*37+Math.sin(y*.09+k)*6,y);c.stroke();}wallTexture=cv;return cv;}
function affineTriangle(c,im,src,dst){const [[x0,y0],[x1,y1],[x2,y2]]=src,[[u0,v0],[u1,v1],[u2,v2]]=dst,D=x0*(y1-y2)+x1*(y2-y0)+x2*(y0-y1);if(Math.abs(D)<1e-7)return;const A=(u0*(y1-y2)+u1*(y2-y0)+u2*(y0-y1))/D,B=(v0*(y1-y2)+v1*(y2-y0)+v2*(y0-y1))/D,C=(u0*(x2-x1)+u1*(x0-x2)+u2*(x1-x0))/D,E=(v0*(x2-x1)+v1*(x0-x2)+v2*(x1-x0))/D,F=(u0*(x1*y2-x2*y1)+u1*(x2*y0-x0*y2)+u2*(x0*y1-x1*y0))/D,G=(v0*(x1*y2-x2*y1)+v1*(x2*y0-x0*y2)+v2*(x0*y1-x1*y0))/D;c.save();c.beginPath();dst.forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.closePath();c.clip();c.transform(A,B,C,E,F,G);c.drawImage(im,0,0);c.restore();}
export function paintHybridFloor(c,time,texture,input={}){if(!texture)return;const f={...hybridDefaults,...input},cam=hybridCamera(time,f),w=texture.naturalWidth||texture.width,h=texture.naturalHeight||texture.height;c.save();const farGround=projectHybrid(imageAnchorWorld(.5,.58,f.hybridBackdropDepth,f),cam)[1];c.beginPath();c.rect(0,farGround-10,960,550-farGround);c.clip();c.fillStyle='#3b3a36';c.fillRect(0,farGround,960,540-farGround);c.filter=`grayscale(1) brightness(${f.hybridSalvageGroundLight})`;for(let zi=1;zi<14;zi++)for(let xi=-4;xi<4;xi++){const a=xi*3,b=(xi+1)*3,z=zi*3,Z=(zi+1)*3,p=[[a,0,z],[b,0,z],[b,0,Z],[a,0,Z]].map(p=>projectHybrid(p,cam));if(p.some(p=>!p))continue;if(p.every(p=>p[1]<0)||p.every(p=>p[0]<0)||p.every(p=>p[0]>960))continue;const uv=[[0,h],[w,h],[w,0],[0,0]];for(const ids of [[0,1,2],[0,2,3]])affineTriangle(c,texture,ids.map(i=>uv[i]),ids.map(i=>p[i]));}c.restore();}
const matteCache=new WeakMap();function streetLayers(im){let old=matteCache.get(im);if(old&&old.src===im.src&&old.revision===im._assetRevision)return old;const w=im.naturalWidth||im.width,h=im.naturalHeight||im.height,base=Object.assign(document.createElement('canvas'),{width:w,height:h}),ctx=base.getContext('2d');ctx.drawImage(im,0,0);ctx.globalCompositeOperation='destination-out';ctx.fillStyle='#fff';ctx.filter='blur(12px)';ctx.beginPath();[[.43,.58],[.57,.58],[.88,1],[.1,1]].forEach(([x,y],i)=>i?ctx.lineTo(x*w,y*h):ctx.moveTo(x*w,y*h));ctx.closePath();ctx.fill();ctx.filter='none';ctx.fillRect(0,0,w*.17,h);old={canvas:base,src:im.src,revision:im._assetRevision};matteCache.set(im,old);return old;}
export function hybridPlateRect(time,depth,input={}){const f={...hybridDefaults,...input},cam=hybridCamera(time,f),tl=projectHybrid(imageAnchorWorld(0,0,depth,f),cam),br=projectHybrid(imageAnchorWorld(1,1,depth,f),cam);return [tl[0],tl[1],br[0]-tl[0],br[1]-tl[1]];}
export function paintHybridStreetPlate(c,time,im,input={}){if(!im)return false;const f={...hybridDefaults,...input},r=hybridPlateRect(time,f.hybridBackdropDepth,f),near=hybridPlateRect(time,f.hybridForegroundDepth,f),s=streetLayers(im),w=im.naturalWidth||im.width,h=im.naturalHeight||im.height;c.save();c.filter=`grayscale(1) brightness(${input.stagingStreetLight??.72})`;const edgeNear=near[0]+near[2]*.17,edgeFar=r[0]+r[2]*.17;c.fillStyle='#252729';c.beginPath();[[edgeNear,near[1]],[edgeFar,r[1]],[edgeFar,r[1]+r[3]],[edgeNear,near[1]+near[3]]].forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.fill();const sideDst=[[edgeNear,near[1]],[edgeFar,r[1]],[edgeFar,r[1]+r[3]],[edgeNear,near[1]+near[3]]],wall=wallMaterial(),sideUV=[[0,0],[256,0],[256,512],[0,512]];c.save();c.globalAlpha=.8;for(const ids of [[0,1,2],[0,2,3]])affineTriangle(c,wall,ids.map(i=>sideUV[i]),ids.map(i=>sideDst[i]));c.restore();c.drawImage(s.canvas,...r);c.drawImage(im,0,0,w*.17,h,near[0],near[1],near[2]*.17,near[3]);c.restore();return {camera:hybridCamera(time,f),near,far:r};}
export function failureSupports(time,input={}){const f={...hybridDefaults,...input};return [0,1,2].map(i=>{const q=smooth((time-f.hybridWireRelease-i*.25)/f.hybridWireFallTime),base=[-4.8+i*.72,0,f.hybridWireNearDepth+4.6+i*1.4],angle=(12+q*(50-i*5))*Math.PI/180,tip=[base[0]+Math.sin(angle)*3.6,Math.cos(angle)*3.6,base[2]+q*.7];return {base,tip,q};});}
export function electricalTopology(time,input={}){const f={...hybridDefaults,...input},anchors=f.hybridWireAnchors||hybridDefaults.hybridWireAnchors,A=imageAnchorWorld(...anchors.left,f.hybridBackdropDepth,f),B=imageAnchorWorld(...anchors.right,f.hybridBackdropDepth,f),wires=[];for(let i=0;i<3;i++)wires.push({id:'overhead-'+i,state:'attached',a:[A[0],A[1]+i*.22,A[2]],b:[B[0],B[1]+i*.22,B[2]],sag:f.hybridWireSag});const supports=failureSupports(time,f);for(let i=0;i<2;i++){const q=supports[i].q,a=[...supports[i].tip],b=[...supports[i+1].tip];a[1]-=.15;b[1]-=.15;wires.push({id:'released-'+i,state:q>=1?'settled':q?'falling':'attached',a,b,sag:f.hybridWireSag+q*.45,q});}return {wires,camera:hybridCamera(time,f)};}
export function sampleHybridWire(wire,u){return [lerp(wire.a[0],wire.b[0],u),Math.max(.035,lerp(wire.a[1],wire.b[1],u)-4*wire.sag*u*(1-u)),lerp(wire.a[2],wire.b[2],u)];}
export function paintHybridWires(c,time,input={}){const f={...hybridDefaults,...input},s=electricalTopology(time,f);c.save();const occluder=hybridPlateRect(time,f.hybridForegroundDepth,f),edge=Math.max(0,occluder[0]+occluder[2]*.17);c.strokeStyle=f.hybridWireDarkness;for(const wire of s.wires){c.lineWidth=f.hybridWireWidth*(wire.id.startsWith('released')?1.2:.8);c.beginPath();let started=false;for(let i=0;i<=32;i++){const p=projectHybrid(sampleHybridWire(wire,i/32),s.camera);if(!p)continue;if(p[2]>f.hybridForegroundDepth-s.camera.z&&p[0]<edge){started=false;continue;}if(!started){c.moveTo(p[0],p[1]);started=true}else c.lineTo(p[0],p[1]);}c.stroke();}
for(const [i,pole] of failureSupports(time,f).entries()){const {base,tip,q}=pole,p=projectHybrid(base,s.camera),P=projectHybrid(tip,s.camera);if(!p||!P)continue;c.strokeStyle='#777a70';c.lineWidth=2.4;c.beginPath();c.moveTo(...p);c.lineTo(...P);c.stroke();const armA=projectHybrid([tip[0]-.42,tip[1],tip[2]],s.camera),armB=projectHybrid([tip[0]+.42,tip[1],tip[2]],s.camera);c.lineWidth=1.4;c.beginPath();c.moveTo(...armA);c.lineTo(...armB);c.stroke();const roof=projectHybrid(imageAnchorWorld(.19,.29+i*.045,f.hybridBackdropDepth,f),s.camera);c.lineWidth=.9;c.beginPath();c.moveTo(...roof);c.lineTo(...P);c.stroke();if(q>.45&&q<.92&&time<(f.stagingSparkStop??22)){const age=(time*7+i*.2)%1;if(age/7>(f.stagingSparkLifetime??.13))continue;for(let j=0;j<Math.max(0,Math.min(40,f.stagingSparkCount??16));j++){c.fillStyle=j%3?'#ffc654':'#fff6cf';c.globalAlpha=(1-age)*(f.expansionSparkStrength??1);const size=f.stagingSparkSize??1.3;c.fillRect(P[0]+Math.sin(j*9)*age*13,P[1]+Math.cos(j*8)*age*8,size,size);}}}c.restore();return s;}
export function salvageCableBinding(input={}){const f={...hybridDefaults,...input},W=f.expansionRuinWidth??8,H=f.expansionRuinHeight??6,X=f.expansionRuinX??4.9,Z=f.expansionRuinDepth??-6,y=H*(1-f.hybridRuinAnchorV),x=X+(f.hybridRuinAnchorU-.5)*W,angle=-8*Math.PI/180,dx=x-X;return {cableAnchorAX:X+dx*Math.cos(angle),cableAnchorAY:y,cableAnchorAZ:Z-dx*Math.sin(angle),cableAnchorBX:X+dx*Math.cos(angle)+f.hybridCableReach,cableAnchorBY:y+f.hybridCableRise,cableAnchorBZ:Z-dx*Math.sin(angle)-.8};}
